    @staticmethod
    def _build_stance_map(unique_constraints, raw_constraints, stance_metadata):
        """Map each UniqueConstraint index to a list of (target, stance, trace_idx)."""
        from .z3_maxsat import parse_z3_formula, check_equivalence

